import{_ as d,a8 as a,o as l,c as n,ah as s,K as e}from"./chunks/framework.CgKDWdj8.js";import"./chunks/theme.CCmhGRzB.js";const u=JSON.parse('{"title":"人工数据合成","description":"","frontmatter":{"title":"人工数据合成","abstract":"人工数据合成方法，讲解真实标注数据不足或存在隐私限制时，通过自动化手段生成带标签训练数据的常见策略与应用。","created":"2026-07-10T00:00:00.000Z","tags":["机器学习","数据增强"],"type":"概念解释","category":["🤖 AI大模型","机器学习"]},"headers":[],"relativePath":"vault/Knowledge/AI/人工数据合成.md","filePath":"vault/Knowledge/AI/人工数据合成.md","lastUpdated":1790655645000}'),i={name:"vault/Knowledge/AI/人工数据合成.md"};function h(_,t,c,p,b,g){const r=a("NolebaseGitContributors"),o=a("NolebaseGitChangelog");return l(),n("div",null,[t[0]||(t[0]=s('<h1 id="人工数据合成" tabindex="-1">人工数据合成 <a class="header-anchor" href="#人工数据合成" aria-label="Permalink to “人工数据合成”">​</a></h1><p>当真实标注数据不足、难以获取或存在隐私限制时，通过自动化手段生成带标签的训练数据。</p><h2 id="常见策略" tabindex="-1">常见策略 <a class="header-anchor" href="#常见策略" aria-label="Permalink to “常见策略”">​</a></h2><table tabindex="0"><thead><tr><th>方法</th><th>原理</th><th>典型工具/场景</th></tr></thead><tbody><tr><td>程序化生成</td><td>规则驱动批量生成</td><td>生成带噪声的印刷体文本图像、3D 渲染场景</td></tr><tr><td>本真数据扰动</td><td>对已有数据做变换扩增</td><td>图像旋转/裁剪/颜色扰动、语音加噪</td></tr><tr><td>GAN/扩散生成</td><td>生成模型产生逼真合成样本</td><td>人脸生成、医学图像合成</td></tr><tr><td>LLM 生成</td><td>大模型生成文本标注数据</td><td>文本分类、QA 对生成、指令数据</td></tr></tbody></table><h2 id="核心要点" tabindex="-1">核心要点 <a class="header-anchor" href="#核心要点" aria-label="Permalink to “核心要点”">​</a></h2><ul><li><strong>覆盖度</strong>：合成数据需覆盖真实分布中的变化因素（角度、光照、噪声等）</li><li><strong>域迁移</strong>：合成数据跟真实数据往往存在分布差异（sim-to-real gap），需用域适应或混合训练</li><li><strong>质量优先</strong>：少量高质量合成数据远优于大量低质量噪声</li><li><strong>一致性</strong>：合成数据可精确控制标签，降低标注成本</li></ul><h2 id="应用" tabindex="-1">应用 <a class="header-anchor" href="#应用" aria-label="Permalink to “应用”">​</a></h2><p>自动驾驶（合成场景）、文档 OCR（合成印刷体）、NLP 分类（LLM 生成）、医疗影像（GAN 生成病变区域）。</p>',8)),e(r),e(o)])}const N=d(i,[["render",h]]);export{u as __pageData,N as default};
